.message-item {
    position: relative;
    padding: 0.5rem 1rem;
    border-radius: 0.25rem;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: rgba(255, 255, 255, 0.03);
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 0.5rem;
    margin-bottom: 0.15rem;
}

.message-author {
    font-weight: 600;
    color: #e0e0e0;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.7rem;
    color: #72767d;
}

.message-content {
    color: #dbdee1;
    font-size: 0.9rem;
    line-height: 1.45;
    word-break: break-word;
}

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.35rem;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.2rem;
    background-color: rgba(88, 101, 242, 0.15);
    border: 1px solid rgba(88, 101, 242, 0.3);
    border-radius: 0.375rem;
    padding: 0.1rem 0.4rem;
    font-size: 0.8rem;
    color: #c4c9ce;
    cursor: default;
}

.thread-link {
    background: none;
    border: none;
    color: #5865f2;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 0.2rem 0;
    margin-top: 0.2rem;
}

.thread-link:hover {
    text-decoration: underline;
}

.message-actions {
    position: absolute;
    top: -0.75rem;
    right: 0.75rem;
    display: flex;
    gap: 0.15rem;
    background-color: #2b2d31;
    border: 1px solid #3a3c42;
    border-radius: 0.375rem;
    padding: 0.15rem;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.25);
}

.action-btn {
    background: none;
    border: none;
    font-size: 1rem;
    cursor: pointer;
    padding: 0.2rem 0.35rem;
    border-radius: 0.25rem;
    line-height: 1;
    transition: background-color 0.1s;
}

.action-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
}

.emoji-picker-container {
    position: absolute;
    top: -0.75rem;
    right: 5rem;
    z-index: 10;
}

