arguments.file_text:
@namespace sv_a39d30bb5b95462d8cdeebda3844f91f.Components.Chat

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <span class="channel-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (IsLoadingMore)
        {
            <div class="loading-indicator">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageItem Message="msg"
                         ThreadSummary="GetThreadSummary(msg.Id)"
                         OnOpenThread="OnOpenThread"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")" OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadOlderMessages { get; set; }

    private ThreadSummary? GetThreadSummary(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top detection is handled via JS interop in the page
        // This is a placeholder for the scroll event binding
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #313338;
}

.message-area-header {
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.05rem;
    color: #fff;
    font-weight: 700;
}

.channel-desc {
    font-size: 0.8rem;
    color: #949ba4;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 0.5rem 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 0.5rem;
    color: #72767d;
    font-size: 0.8rem;
}

@namespace sv_a39d30bb5b95462d8cdeebda3844f91f.Components.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <div class="root-author">@RootMessage.Author</div>
            <div class="root-content">@RootMessage.Content</div>
        </div>
    }

    <div class="thread-divider">
        <span>@ThreadMessages.Count @(ThreadMessages.Count == 1 ? "reply" : "replies")</span>
    </div>

    <div class="thread-messages">
        @foreach (var msg in ThreadMessages)
        {
            <MessageItem Message="msg"
                         OnOpenThread="EventCallback<int>.Empty"
                         OnReact="OnReact" />
        }
    </div>

    <MessageInput Placeholder="Reply in thread…"
                  ButtonLabel="Reply"
                  OnSend="OnSendReply" />
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter, EditorRequired] public List<Message> ThreadMessages { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2b2d31;
    border-left: 1px solid #1e1f22;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #fff;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 0.2rem 0.4rem;
    border-radius: 0.25rem;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root-message {
    padding: 0.75rem 1rem;
    background-color: rgba(255, 255, 255, 0.03);
    border-bottom: 1px solid #1e1f22;
    flex-shrink: 0;
