arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@using sv_a39d30bb5b95462d8cdeebda3844f91f.Components.Chat
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelList Channels="_channels"
                     ActiveChannelId="_activeChannelId"
                     OnChannelSelected="SelectChannelAsync" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "chat-main-full")">
        @if (_activeChannel is not null)
        {
            <MessageArea ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         IsLoadingMore="_loadingMore"
                         OnOpenThread="OpenThreadAsync"
                         OnReact="HandleReactionAsync"
                         OnSendMessage="SendMessageAsync"
                         OnLoadOlderMessages="LoadOlderMessagesAsync" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReplyAsync"
                         OnReact="HandleReactionAsync" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = new();
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();
    private List<Message> _threadMessages = new();
    private Channel? _activeChannel;
    private int _activeChannelId;
    private Message? _threadRootMessage;
    private bool _threadOpen;
    private bool _loadingMore;
    private int _messageSkip;
    private const int PageSize = 50;

    private IJSObjectReference? _scrollModule;
    private DotNetObjectReference<Chat>? _dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannelAsync(_channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/Pages/Chat.razor.js");
            await _scrollModule.InvokeVoidAsync("initScrollDetection", ".message-list", _dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (_loadingMore || _activeChannel is null) return;
        await LoadOlderMessagesAsync();
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messageSkip = 0;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _messageSkip = _messages.Count;
        _threadSummaries = BuildThreadSummaries(_messages);
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the channel's unread count locally
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_activeChannel is null) return;
        _loadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannel.Id, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _messageSkip += older.Count;
            _threadSummaries = BuildThreadSummaries(_messages);
        }
        _loadingMore = false;
    }

    private async Task SendMessageAsync(string content)
    {
        if (_activeChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_activeChannel.Id, content, null);
        _messages.Add(msg);
        _messageSkip++;
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadMessages.Clear();
    }

    private async Task SendThreadReplyAsync(string content)
    {
        if (_threadRootMessage is null || _activeChannel is null) return;
        var reply = await ChatService.SendMessageAsync(
            _activeChannel.Id, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);

        // Update thread summary in the main message list
        _threadSummaries = BuildThreadSummaries(_messages, _threadRootMessage.Id, _threadMessages.Count);
    }

    private async Task HandleReactionAsync((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update for the reaction in the messages list
        UpdateReactionInList(_messages, args.MessageId, args.Emoji);
        UpdateReactionInList(_threadMessages, args.MessageId, args.Emoji);
    }

    private static void UpdateReactionInList(List<Message> messages, int messageId, string emoji)
    {
        var msg = messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is null) return;

        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing is not null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
        }
    }

    private static List<ThreadSummary> BuildThreadSummaries(
        List<Message> messages, int? overrideId = null, int? overrideCount = null)
    {
        var rootIds = messages
            .Where(m => m.ReplyToId is not null)
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g =>
            {
                int count = overrideId == g.Key ? overrideCount!.Value : g.Count();
                return new ThreadSummary(g.Key, count, g.Max(m => m.SentAt));
            })
            .ToList();

        return rootIds;
    }

    public async ValueTask DisposeAsync()
    {
        if (_scrollModule is not null)
        {
            try { await _scrollModule.DisposeAsync(); }
            catch (JSDisconnectedException) { }
        }
        _dotNetRef?.Dispose();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    color: #dbdee1;
    background-color: #313338;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
}

.chat-main-full {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 420px;
    flex-shrink: 0;
}

.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #72767d;
    font-size: 1.1rem;
}

export function initScrollDetection(selector, dotNetRef) {
    const el = document.querySelector(selector);
    if (!el) return;

    el.addEventListener('scroll', () => {
        if (el.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    });
}

